package com.daraya.atoconstrucciones.treasury;
import com.daraya.atoconstrucciones.identity.IdentityService;
import jakarta.validation.Valid;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import java.net.URI;
import java.util.*;

@RestController @RequestMapping("/api/v1")
public class TreasuryController {
    private final TreasuryService treasury;private final IdentityService identity;
    public TreasuryController(TreasuryService treasury,IdentityService identity) {this.treasury=treasury;this.identity=identity;}
    private <T> ResponseEntity<T> result(T value,long version,int status,String path) {var builder=ResponseEntity.status(status).cacheControl(CacheControl.noStore()).eTag("\""+version+"\"");if(status==201)builder.location(URI.create(path));return builder.body(value);}
    @GetMapping("/treasury/accounts") public List<TreasuryService.Account> accounts(Authentication a) {return treasury.accounts(identity.actor(a));}
    @GetMapping("/projects/{p}/treasury-accounts") public List<TreasuryService.Account> projectAccounts(Authentication a,@PathVariable UUID p) {return treasury.projectAccounts(identity.actor(a),p);}
    @PostMapping("/treasury/accounts") public ResponseEntity<TreasuryService.Account> account(Authentication a,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody TreasuryService.AccountInput i) {var v=treasury.account(identity.actor(a),key,i);return ResponseEntity.created(URI.create("/api/v1/treasury/accounts/"+v.id())).cacheControl(CacheControl.noStore()).body(v);}
    @GetMapping("/projects/{p}/treasury-movements") public List<TreasuryService.Movement> list(Authentication a,@PathVariable UUID p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size) {return treasury.list(identity.actor(a),p,page,size);}
    @GetMapping("/treasury/movements/{id}") public ResponseEntity<TreasuryService.Movement> read(Authentication a,@PathVariable UUID id) {var v=treasury.read(identity.actor(a),id);return result(v,v.version(),200,"");}
    @PostMapping("/treasury/movements") public ResponseEntity<TreasuryService.Movement> create(Authentication a,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody TreasuryService.MovementInput i) {var v=treasury.create(identity.actor(a),key,i);return result(v,v.version(),201,"/api/v1/treasury/movements/"+v.id());}
    @PostMapping("/treasury/movements/{id}/confirm") public ResponseEntity<TreasuryService.Movement> confirm(Authentication a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String etag,@Valid @RequestBody TreasuryService.Decision i) {var v=treasury.confirm(identity.actor(a),id,key,etag,i);return result(v,v.version(),200,"");}
    @PostMapping("/treasury/movements/{id}/reverse") public ResponseEntity<TreasuryService.Movement> reverse(Authentication a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String etag,@Valid @RequestBody TreasuryService.Reverse i) {var v=treasury.reverse(identity.actor(a),id,key,etag,i);return result(v,v.version(),200,"");}
    @PostMapping("/treasury/movements/{id}/payment-allocations") public ResponseEntity<TreasuryService.Movement> apply(Authentication a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String etag,@Valid @RequestBody TreasuryService.Application i) {var v=treasury.apply(identity.actor(a),id,key,etag,i);return result(v,v.version(),200,"");}
    @PostMapping("/treasury/movements/{id}/collection-allocations") public ResponseEntity<TreasuryService.Movement> collect(Authentication a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String etag,@Valid @RequestBody TreasuryService.CollectionInput i) {var v=treasury.collect(identity.actor(a),id,key,etag,i);return result(v,v.version(),200,"");}
    @PostMapping("/treasury/transfers") public ResponseEntity<TreasuryService.Movement> transfer(Authentication a,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody TreasuryService.TransferInput i) {var v=treasury.transfer(identity.actor(a),key,i);return result(v,v.version(),201,"/api/v1/treasury/movements/"+v.id());}
    @GetMapping("/projects/{p}/deposit-reports") public List<TreasuryService.Deposit> deposits(Authentication a,@PathVariable UUID p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size) {return treasury.deposits(identity.actor(a),p,page,size);}
    @GetMapping("/projects/{p}/deposit-reports/{id}") public ResponseEntity<TreasuryService.Deposit> deposit(Authentication a,@PathVariable UUID p,@PathVariable UUID id) {var v=treasury.readDeposit(identity.actor(a),p,id);return result(v,v.version(),200,"");}
    @PostMapping("/projects/{p}/deposit-reports") public ResponseEntity<TreasuryService.Deposit> report(Authentication a,@PathVariable UUID p,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody TreasuryService.DepositInput i) {var v=treasury.report(identity.actor(a),p,key,i);return result(v,v.version(),201,"/api/v1/projects/"+p+"/deposit-reports/"+v.id());}
    @PostMapping("/projects/{p}/deposit-reports/{id}/confirm") public ResponseEntity<TreasuryService.Deposit> confirmDeposit(Authentication a,@PathVariable UUID p,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String etag,@Valid @RequestBody TreasuryService.ConfirmDeposit i) {var v=treasury.confirmDeposit(identity.actor(a),p,id,key,etag,i);return result(v,v.version(),200,"");}
    @PostMapping("/projects/{p}/deposit-reports/{id}/{action:review|reject}") public ResponseEntity<TreasuryService.Deposit> decideDeposit(Authentication a,@PathVariable UUID p,@PathVariable UUID id,@PathVariable String action,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String etag,@Valid @RequestBody TreasuryService.Decision i) {var v=treasury.reviewDeposit(identity.actor(a),p,id,key,etag,action,i);return result(v,v.version(),200,"");}
}
